item.command:
/bin/bash -c 'set -o pipefail
for i in 1 2; do
  case "$i" in
    1) q='"'\"G.L.Bajaj Institute of Technology and Management\" official website';;
    2) q='G L Bajaj Institute of Technology and Management Greater Noida admissions courses official';;
  esac
  out=\""'$TMPDIR/glbaj-research/search_$i.html"
  echo "=== QUERY $q ==="
  curl -L --fail --silent --show-error --max-time 30 --get '"'https://www.google.com/search' --data-urlencode \"q="'$q" -o "$out" || {
    echo '"'GOOGLE_FAILED'; continue;
  }
  echo \"SAVED "'$out ($(wc -c < "$out") bytes)"
  rg -o '"'https?://["'^"& ]+'"' \""'$out" | sed '"'s/\\\\u003d/=/g;s/\\\\u0026/\\&/g' | rg -i 'glbitm|bajaj|google' | sed -n '1,40p' || true
done"

